-- Migration 20261019140100: Closeout (technician portal stop 3)
--
-- closeout_outcome gains 'partial_expertise' (outcome 3 « Call partiellement
-- fait, besoin d'une expertise »). Outcome 4 reuses the existing 'failed'
-- (« Call pas du tout fait » — SoW wording, documented in the type comment).
-- maintenance_request.closeout_urgent — the « Urgent » checkbox on outcomes
-- 3/4 (client source: reference §6.1 "option Urgente"). Separate from
-- urgency_tier (tier sources conflict, reference §3).
-- maintenance_attachment.attachment_id: checked 2026-10-19 — it is ALREADY
-- GENERATED BY DEFAULT AS IDENTITY (information_schema.is_identity = YES;
-- the earlier "no default" finding misread column_default, which is NULL for
-- identity columns). The table is empty, so the sequence needs no setval.
-- No change required. visit_id marks a photo as consumed by a closeout —
-- the "not yet used" rule.
-- request_visit.closeout_comment — per-visit comment for the coordinator's
-- visit history (also written to the follow-up log).
--
-- The private bucket request-photos is declared in supabase/config.toml
-- (created on stack start); the guarded INSERT below makes it exist without
-- a restart, and is a no-op on databases without the storage schema
-- (sib_test) and on conflict.

BEGIN;

ALTER TYPE public.closeout_outcome ADD VALUE IF NOT EXISTS 'partial_expertise';

COMMENT ON TYPE public.closeout_outcome IS
    'Closeout outcomes (reference §6.1, François''s four): complete = « Call fermé, terminé complètement »; partial_reschedule = « Call partiellement fait, je dois revenir »; partial_expertise = « Call partiellement fait, besoin d''une expertise »; failed = « Call pas du tout fait, besoin d''une expertise / envoyer à dispatch ».';

ALTER TABLE public.maintenance_request
    ADD COLUMN closeout_urgent boolean;

-- attachment_id is already GENERATED BY DEFAULT AS IDENTITY — see header.

ALTER TABLE public.maintenance_attachment
    ADD COLUMN visit_id integer REFERENCES public.request_visit(visit_id);
COMMENT ON COLUMN public.maintenance_attachment.visit_id IS
    'Set when a closeout consumes the photo; NULL = uploaded, not yet used.';

ALTER TABLE public.request_visit
    ADD COLUMN closeout_comment text;

DO $$
BEGIN
    IF EXISTS (SELECT FROM information_schema.tables
               WHERE table_schema = 'storage' AND table_name = 'buckets') THEN
        INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
        VALUES ('request-photos', 'request-photos', false, 10485760,
                ARRAY['image/jpeg', 'image/png', 'image/webp'])
        ON CONFLICT (id) DO NOTHING;
    END IF;
END $$;

COMMIT;

-- ── Rollback ─────────────────────────────────────────────────────────────────
/*
