ALTER TABLE public.maintenance_attachment DROP COLUMN IF EXISTS visit_id;
ALTER TABLE public.maintenance_request DROP COLUMN IF EXISTS closeout_urgent;
-- enum values cannot be dropped; 'partial_expertise' stays.
COMMIT;
*/
